import collections
import heapq

class TrieNode:
    def __init__(self):
        self.children: dict[str, TrieNode] = {}
        self.count = 0

class Trie:
    def __init__(self, k: int):
        self.k = k
        self.root = TrieNode()
        self.prefixLengthsCount = collections.Counter()
        self.max_heap = []

    def insert(self, word: str) -> None:
        node = self.root
        for i, c in enumerate(word):
            sz = i + 1
            node = node.children.setdefault(c, TrieNode())
            node.count += 1
            if node.count >= self.k:
                self.prefixLengthsCount[sz] += 1
                if self.prefixLengthsCount[sz] == 1:
                    heapq.heappush(self.max_heap, -sz)

    def erase(self, word: str) -> None:
        node = self.root
        for i, c in enumerate(word):
            sz = i + 1
            node = node.children[c]
            if node.count == self.k:
                self.prefixLengthsCount[sz] -= 1
            node.count -= 1

    def getLongestCommonPrefix(self) -> int:
        while self.max_heap and self.prefixLengthsCount[-self.max_heap[0]] == 0:
            heapq.heappop(self.max_heap)
        return -self.max_heap[0] if self.max_heap else 0

class Solution:
    def longestCommonPrefix(self, words: list[str], k: int) -> list[int]:
        ans = []
        trie = Trie(k)
        for word in words:
            trie.insert(word)
        for word in words:
            trie.erase(word)
            ans.append(trie.getLongestCommonPrefix())
            trie.insert(word)
        return ans

